import Foundation

/// Trait names and the two ends of each, from frontend/src/traits.ts (the
/// keys match backend/content.go). Each end carries its kind strength line and
/// one way to grow. Used to word a read or a reflection; never a verdict.
public enum Traits {
    public struct Side: Sendable, Hashable {
        public let lean: String
        public let headline: String
        public let strength: String
        public let grow: String
    }

    public struct Trait: Sendable, Hashable {
        public let name: String
        public let high: Side
        public let low: Side
    }

    public static let all: [String: Trait] = [
        "conscientiousness": Trait(name: "Getting things done", high: Side(lean: "getting things done", headline: "You finish what you start.", strength: "You tend to finish what you start, and people rely on you for it.", grow: "Leave one small thing undone on purpose each day, so your rest stops depending on a cleared list."), low: Side(lean: "keeping plans loose", headline: "You keep your plans loose.", strength: "You keep plans loose, which helps you adapt when the day changes.", grow: "Give one task a day a fixed moment, like 'right after lunch', so the important things get done without a full schedule.")),
        "agreeableness": Trait(name: "Keeping the peace", high: Side(lean: "keeping the peace", headline: "You keep the peace.", strength: "You keep the peace, and people feel safe around you.", grow: "Practise one honest 'no' this week; kindness lasts longer when it includes you too."), low: Side(lean: "saying what you think", headline: "You say what you think.", strength: "You say what you think, which makes you a clear and useful voice.", grow: "Ask one question before you give your view; people hear directness better when they feel heard first.")),
        "openness": Trait(name: "Openness to new things", high: Side(lean: "trying new things", headline: "You reach for the new.", strength: "You reach for the new, which keeps life fresh and makes you good at spotting other ways of doing things.", grow: "Pick one new interest and stay with it for a month, so curiosity turns into real skill."), low: Side(lean: "sticking with what works", headline: "You trust what works.", strength: "You value what works, and that makes you steady and dependable.", grow: "Try one small unfamiliar thing a week, a new route or a new dish, and notice what it teaches you.")),
        "extraversion": Trait(name: "Energy from people", high: Side(lean: "time with people", headline: "People charge you up.", strength: "People charge you up, and you likely lift the energy of a room.", grow: "Protect some quiet time each week; it is where your best ideas tend to settle."), low: Side(lean: "time on your own", headline: "You recharge on your own.", strength: "You recharge alone and choose company with care, so your friendships tend to run deep.", grow: "Say yes to one low-key invitation this week; small doses of company can refresh you too.")),
        "neuroticism": Trait(name: "Worry and tension", high: Side(lean: "worry", headline: "Things stay with you.", strength: "Things stay on your mind, which often means you care and notice early warning signs.", grow: "Give worries a short, set time each day and write them down; a written worry tends to feel smaller."), low: Side(lean: "staying calm", headline: "Setbacks roll off you.", strength: "Setbacks roll off you, and others may lean on your calm.", grow: "Check in on people around you after hard moments; they may still be carrying what you have already set down.")),
        "honesty_humility": Trait(name: "Fairness", high: Side(lean: "playing fair", headline: "You play fair, even unseen.", strength: "You hold to fair play even when no one is watching, and that builds deep trust.", grow: "Let yourself ask for credit when you have earned it; fairness includes being fair to yourself."), low: Side(lean: "bending the rules", headline: "You treat rules as flexible.", strength: "You treat rules as flexible, which can make you resourceful under pressure.", grow: "Before bending a rule, picture the person who pays for it; the shortcut often looks different with a face on it.")),
        "attachment_anxiety": Trait(name: "Reading closeness", high: Side(lean: "watching for distance", headline: "You notice distance fast.", strength: "You watch closely for signs of distance, which makes you attentive to the people you love.", grow: "When a silence worries you, ask directly instead of guessing; one simple question tends to bring more calm than hours of reading signs."), low: Side(lean: "trusting the quiet", headline: "Silence doesn't rattle you.", strength: "You rarely read distance as being about you, and that security makes you easy to be close to.", grow: "Reach out first now and then; others may need the reassurance you do not.")),
        "attachment_avoidance": Trait(name: "Keeping space", high: Side(lean: "keeping your space", headline: "You keep a little space.", strength: "You keep some space, even with people you are close to, and you stand well on your own.", grow: "Share one small worry with someone you trust this week; letting people help is a skill too."), low: Side(lean: "letting people in", headline: "You let people in.", strength: "You let people in easily, and they feel welcome around you.", grow: "Keep a little time just for yourself each week, so closeness stays a choice rather than a habit.")),
        "present_bias": Trait(name: "Now versus later", high: Side(lean: "now over later", headline: "Now tends to win.", strength: "The reward in front of you tends to win, which makes you good at enjoying the moment.", grow: "Pause ten minutes before buying or saying yes to anything; the bigger reward often wins once you wait."), low: Side(lean: "waiting for better", headline: "You'll wait for better.", strength: "You will wait for the better result, and that patience tends to pay off.", grow: "Plan one small treat this week with no purpose at all; the future is easier to save for when the present feels good too.")),
        "rumination": Trait(name: "Replaying", high: Side(lean: "replaying hard moments", headline: "You replay hard moments.", strength: "You replay hard moments, which shows how much you care about getting things right.", grow: "When a replay starts, get moving: walk, tidy or call someone. Busy hands tend to quiet a looping mind."), low: Side(lean: "letting things go", headline: "You let things go.", strength: "Once something is over you let it go, which keeps your days light.", grow: "After big moments, take one minute to ask what you would do differently; a short look back turns experience into wisdom.")),
        "materialism": Trait(name: "Things or experiences", high: Side(lean: "owning things", headline: "Owning things matters to you.", strength: "Owning things you want matters to you, and you likely care about quality and comfort.", grow: "Before your next purchase, ask what experience it will give you; the things that last are often tied to good memories."), low: Side(lean: "doing over owning", headline: "You'd rather do than own.", strength: "You would rather spend on doing than owning, which tends to bring lasting joy.", grow: "Make sure the basics are covered first; experiences feel even better when bills are not on your mind.")),
    ]
}
